/** GD Goenka University - Enrollment Number Generator (Java Swing edition). */
public class EnrollmentPortal extends JFrame {
    private static final Color PURPLE = new Color(113,89,223), DARK = new Color(89,66,197), PALE = new Color(238,234,255), BG = new Color(248,247,252), TEXT = new Color(48,42,67), MUTED = new Color(137,131,155), LINE = new Color(233,229,242), GREEN = new Color(49,155,117), RED = new Color(223,88,112);
    private static final String DATA_FILE = "enrollment-data.ser";
    private static final List<String> DEFAULT_COURSES = Arrays.asList("B.Tech CSE","B.Tech Civil Engineering","B.Tech ECE","B.Tech CSE - AI & ML","B.Tech AI & Data Science","B.Tech Cyber Security","B.Tech Biotechnology","B.Tech Aerospace","B.Tech Energy","B.Tech Mechanical Engineering (EV)","B.Tech Fire & Safety","B.Tech Environmental (ESG & Sustainability)","B.Tech ECE Biomedical (BOSCH)","B.Tech ECE IoT (BOSCH)","B.Tech ECE VLSI (BOSCH)","B.Tech ECE Quantum Technology","B.Tech CSE Quantum Computing","B.Tech Aerospace with Pilot Pathway","BCA Cyber Security (CompTIA)","BCA AI/ML (Microsoft CloudThat)","BCA Data Science (Microsoft CloudThat)");
    private static final List<String> DEFAULT_YEARS = Arrays.asList("2025-2026","2026-2027","2027-2028","2028-2029");
    static class Student implements Serializable {
        String id,name,email,phone,course,year,enrollment,dob="",gender="",address="";
        Student(String id,String n,String e,String p,String c,String y,String en){id=id;this.id=id;name=n;email=e;phone=p;course=c;year=y;enrollment=en;}
    }
    static class Store implements Serializable {
        List<Student> students=new ArrayList<>(); List<String> courses=new ArrayList<>(DEFAULT_COURSES), years=new ArrayList<>(DEFAULT_YEARS);
        String username="admin", password="admin@123"; long counter=203123;
    }
    private Store data = new Store();
    private final CardLayout cards = new CardLayout(); private final JPanel root = new JPanel(cards);
    private String currentEnrollment=""; private Student selected;
    private JTextField regName,regEmail,regPhone,findPhone,findEmail,loginUser,courseInput,yearInput,searchInput;
    private JPasswordField loginPass,currentPass,newPass,confirmPass;
    private JComboBox<String> regCourse,regYear,yearFilter,courseFilter,detailCourse,detailYear,detailGender;
    private JLabel regMsg,findMsg,findResult,loginMsg,successNumber,totalLabel,copyMsg,credentialMsg,detailTitle,detailEnroll,detailAvatar,editMsg;
    private JPanel courseList,yearList,studentList; private JTextField dName,dEnroll,dPhone,dEmail,dDob,dAddress;
    private JButton editBtn,deleteBtn,saveEditBtn,cancelEditBtn; private JPanel editActions;

    public EnrollmentPortal(){ super("GD Goenka | Enrollment Portal"); load(); setDefaultCloseOperation(EXIT_ON_CLOSE); setMinimumSize(new Dimension(900,680)); setSize(1180,820); setLocationRelativeTo(null); getContentPane().setBackground(BG); root.setBackground(BG); setContentPane(root); buildScreens(); cards.show(root,"splash"); javax.swing.Timer t=new javax.swing.Timer(1600,e->cards.show(root,"home")); t.setRepeats(false); t.start(); }
    private void load(){ try(ObjectInputStream in=new ObjectInputStream(Files.newInputStream(Paths.get(DATA_FILE)))){data=(Store)in.readObject();}catch(Exception ignored){} }
    private void save(){ try(ObjectOutputStream out=new ObjectOutputStream(Files.newOutputStream(Paths.get(DATA_FILE)))){out.writeObject(data);}catch(IOException ex){msg("Storage error", "Could not save data: "+ex.getMessage());} }
    private void buildScreens(){ root.add(splash(),"splash"); root.add(home(),"home"); root.add(studentHome(),"student"); root.add(registration(),"register"); root.add(findPage(),"find"); root.add(successPage(),"success"); root.add(adminLogin(),"login"); root.add(dashboard(),"dashboard"); root.add(studentDetails(),"details"); }
    private JPanel page(){ JPanel p=new JPanel();p.setBackground(BG);p.setBorder(new EmptyBorder(28,34,32,34));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));return p; }
    private JPanel card(){ JPanel p=new JPanel();p.setBackground(Color.WHITE);p.setBorder(new CompoundBorder(new LineBorder(LINE),new EmptyBorder(26,28,26,28)));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));return p; }
    private JLabel heading(String s,int size){JLabel l=new JLabel(s);l.setFont(new Font("SansSerif",Font.BOLD,size));l.setForeground(TEXT);return l;}
    private JLabel eyebrow(String s){JLabel l=new JLabel(s.toUpperCase());l.setFont(new Font("SansSerif",Font.BOLD,10));l.setForeground(PURPLE);return l;}
    private JLabel muted(String s){JLabel l=new JLabel(s);l.setForeground(MUTED);l.setFont(new Font("SansSerif",Font.PLAIN,13));return l;}
    private JButton button(String text,boolean primary){JButton b=new JButton(text);b.setFocusPainted(false);b.setFont(new Font("SansSerif",Font.BOLD,12));b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));b.setBorder(new EmptyBorder(12,18,12,18));b.setBackground(primary?PURPLE:Color.WHITE);b.setForeground(primary?Color.WHITE:TEXT);if(!primary)b.setBorder(new CompoundBorder(new LineBorder(LINE),new EmptyBorder(11,17,11,17)));return b;}
    private JTextField field(String hint){JTextField f=new JTextField();f.setFont(new Font("SansSerif",Font.PLAIN,14));f.setForeground(TEXT);f.setBorder(new CompoundBorder(new LineBorder(LINE),new EmptyBorder(11,12,11,12)));f.setToolTipText(hint);return f;}
    private void addField(JPanel p,String label,JComponent c){JPanel w=new JPanel(new BorderLayout(0,7));w.setOpaque(false);JLabel l=new JLabel(label.toUpperCase());l.setFont(new Font("SansSerif",Font.BOLD,10));l.setForeground(MUTED);w.add(l,BorderLayout.NORTH);w.add(c,BorderLayout.CENTER);w.setMaximumSize(new Dimension(Integer.MAX_VALUE,72));p.add(w);p.add(Box.createVerticalStrut(13));}
    private JPanel splash(){JPanel p=new JPanel(new GridBagLayout());p.setBackground(BG);JPanel c=new JPanel();c.setOpaque(false);c.setLayout(new BoxLayout(c,BoxLayout.Y_AXIS));JLabel logo=heading("G",38);logo.setForeground(Color.WHITE);logo.setOpaque(true);logo.setBackground(PURPLE);logo.setHorizontalAlignment(SwingConstants.CENTER);logo.setPreferredSize(new Dimension(72,72));logo.setMaximumSize(new Dimension(72,72));logo.setAlignmentX(.5f);c.add(logo);c.add(Box.createVerticalStrut(22));JLabel uni=eyebrow("GD GOENKA UNIVERSITY");uni.setAlignmentX(.5f);c.add(uni);c.add(Box.createVerticalStrut(12));JLabel title=heading("Enrollment Number Generator",30);title.setAlignmentX(.5f);c.add(title);JLabel sub=muted("PRECISION  •  IDENTITY  •  EXCELLENCE");sub.setAlignmentX(.5f);c.add(sub);JProgressBar bar=new JProgressBar();bar.setIndeterminate(true);bar.setForeground(PURPLE);bar.setMaximumSize(new Dimension(270,5));c.add(Box.createVerticalStrut(35));c.add(bar);p.add(c);return p;}
    private JPanel home(){JPanel p=new JPanel(new GridBagLayout());p.setBackground(BG);JPanel c=card();c.setPreferredSize(new Dimension(520,390));c.setAlignmentX(.5f);JLabel logo=heading("G",26);logo.setForeground(PURPLE);c.add(logo);c.add(eyebrow("GD GOENKA UNIVERSITY"));c.add(Box.createVerticalStrut(10));c.add(heading("Welcome Back.",32));c.add(muted("Select your portal to continue."));c.add(Box.createVerticalStrut(24));JButton a=button("♙   Admin Portal     —     Manage student enrollment records",false);a.setAlignmentX(LEFT_ALIGNMENT);a.addActionListener(e->show("login"));JButton s=button("▣   Student Portal   —     Register or find your enrollment number",false);s.setAlignmentX(LEFT_ALIGNMENT);s.addActionListener(e->show("student"));c.add(a);c.add(Box.createVerticalStrut(12));c.add(s);c.add(Box.createVerticalStrut(22));c.add(eyebrow("PRECISION  •  IDENTITY  •  EXCELLENCE"));p.add(c);return p;}
    private JPanel studentHome(){JPanel p=page();p.add(nav("Back",()->show("home")));p.add(Box.createVerticalStrut(30));p.add(eyebrow("STUDENT PORTAL"));p.add(heading("How can we help you?",30));p.add(muted("Choose an option to continue."));p.add(Box.createVerticalStrut(24));JButton r=button("＋   Create a New Enrollment Number     →",false);r.setAlignmentX(LEFT_ALIGNMENT);r.addActionListener(e->{refreshRegistrationOptions();show("register");});JButton f=button("⌕   Find My Enroll     →",false);f.setAlignmentX(LEFT_ALIGNMENT);f.addActionListener(e->show("find"));p.add(r);p.add(Box.createVerticalStrut(12));p.add(f);return p;}
    private JButton nav(String t,Runnable r){JButton b=button("← "+t,false);b.setBorder(new EmptyBorder(8,0,8,8));b.setForeground(MUTED);b.setAlignmentX(LEFT_ALIGNMENT);b.addActionListener(e->r.run());return b;}
    private JPanel registration(){JPanel p=page();p.add(nav("Back to student portal",()->show("student")));p.add(Box.createVerticalStrut(18));p.add(eyebrow("NEW STUDENT REGISTRATION"));p.add(heading("Begin your journey.",30));p.add(muted("Enter your details to generate your enrollment number."));p.add(Box.createVerticalStrut(20));JPanel c=card();regName=field("Enter your full name");regEmail=field("Enter your email address");regPhone=field("Enter phone number");regCourse=new JComboBox<>();regYear=new JComboBox<>();addField(c,"Full Name",regName);addField(c,"Email Address",regEmail);addField(c,"Phone Number",regPhone);addField(c,"Course",regCourse);addField(c,"Academic Year",regYear);regMsg=message();c.add(regMsg);JButton submit=button("Generate Enrollment Number   →",true);submit.addActionListener(e->registerStudent());c.add(submit);p.add(c);return p;}
    private void refreshRegistrationOptions(){regCourse.setModel(new DefaultComboBoxModel<>(data.courses.toArray(new String[0])));regYear.setModel(new DefaultComboBoxModel<>(data.years.toArray(new String[0])));regCourse.setSelectedIndex(-1);regYear.setSelectedIndex(-1);}
    private JLabel message(){JLabel l=new JLabel(" ");l.setFont(new Font("SansSerif",Font.PLAIN,12));l.setForeground(RED);return l;}
    private void setMsg(JLabel l,String s,boolean ok){l.setText(s);l.setForeground(ok?GREEN:RED);}
    private JPanel findPage(){JPanel p=page();p.add(nav("Back",()->show("student")));p.add(Box.createVerticalStrut(18));p.add(eyebrow("STUDENT PORTAL"));p.add(heading("Find My Enrollment.",30));p.add(muted("Enter your registered details to retrieve your enrollment number."));p.add(Box.createVerticalStrut(20));JPanel c=card();findPhone=field("Registered phone number");findEmail=field("Registered email address");addField(c,"Phone Number",findPhone);addField(c,"Email Address",findEmail);findMsg=message();findResult=muted("");c.add(findMsg);JButton b=button("Find Enrollment Number   →",true);b.addActionListener(e->findEnrollment());c.add(b);c.add(Box.createVerticalStrut(12));c.add(findResult);p.add(c);return p;}
    private JPanel successPage(){JPanel p=new JPanel(new GridBagLayout());p.setBackground(BG);JPanel c=card();c.setPreferredSize(new Dimension(560,390));JLabel tick=heading("✓",36);tick.setForeground(GREEN);c.add(tick);c.add(eyebrow("REGISTRATION SUCCESSFUL"));c.add(heading("You're officially enrolled!",27));c.add(muted("Your enrollment number has been generated successfully."));c.add(Box.createVerticalStrut(24));c.add(eyebrow("YOUR ENROLLMENT NUMBER"));successNumber=heading("",30);successNumber.setForeground(PURPLE);c.add(successNumber);JButton copy=button("Copy Number",false);copy.addActionListener(e->{Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(currentEnrollment),null);setMsg(copyMsg,"Enrollment number copied successfully!",true);});c.add(copy);copyMsg=message();c.add(copyMsg);JButton cont=button("Continue",true);cont.addActionListener(e->show("student"));JButton print=button("Print Confirmation",false);print.addActionListener(e->{JTextArea a=new JTextArea("GD GOENKA UNIVERSITY\nREGISTRATION CONFIRMATION\n\nEnrollment Number: "+currentEnrollment);try{a.print();}catch(PrinterException ex){msg("Print",ex.getMessage());}});JPanel row=new JPanel(new FlowLayout(FlowLayout.CENTER));row.setOpaque(false);row.add(cont);row.add(print);c.add(row);p.add(c);return p;}
    private JPanel adminLogin(){JPanel p=new JPanel(new GridBagLayout());p.setBackground(BG);JPanel c=card();c.setPreferredSize(new Dimension(450,490));c.add(nav("Back",()->show("home")));c.add(heading("G",28));c.add(eyebrow("ADMINISTRATOR PORTAL"));c.add(heading("Admin Login.",30));c.add(muted("Sign in to manage student records."));c.add(Box.createVerticalStrut(18));loginUser=field("Enter username");loginPass=new JPasswordField();loginPass.setBorder(new CompoundBorder(new LineBorder(LINE),new EmptyBorder(11,12,11,12)));addField(c,"Username",loginUser);addField(c,"Password",loginPass);JButton toggle=button("Show / Hide password",false);toggle.addActionListener(e->loginPass.setEchoChar(loginPass.getEchoChar()==0?'•':(char)0));c.add(toggle);loginMsg=message();c.add(loginMsg);JButton b=button("Sign In   →",true);b.addActionListener(e->{if(loginUser.getText().trim().equals(data.username)&&new String(loginPass.getPassword()).equals(data.password)){renderDashboard();show("dashboard");}else setMsg(loginMsg,"Invalid username or password. Please try again.",false);});c.add(b);c.add(Box.createVerticalStrut(18));c.add(muted("Default login: admin / admin@123"));p.add(c);return p;}
    private JPanel dashboard(){JPanel p=page();JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);JLabel brand=heading("G   Enrollment Portal  |  GD Goenka University",17);top.add(brand,BorderLayout.WEST);JButton logout=button("Logout ↗",false);logout.addActionListener(e->show("home"));top.add(logout,BorderLayout.EAST);p.add(top);p.add(Box.createVerticalStrut(25));p.add(eyebrow("ADMINISTRATION"));p.add(heading("Student Records.",30));p.add(muted("View and manage university enrollment information."));p.add(Box.createVerticalStrut(16));totalLabel=heading("TOTAL STUDENTS: 0",19);p.add(totalLabel);p.add(Box.createVerticalStrut(18));JTabbedPane tabs=new JTabbedPane();tabs.addTab("Students",studentManagement());tabs.addTab("Courses & Years",settingsPanel());tabs.addTab("Admin Credentials",credentialsPanel());p.add(tabs);return p;}
    private JPanel studentManagement(){JPanel c=new JPanel(new BorderLayout(8,12));c.setBackground(Color.WHITE);c.setBorder(new EmptyBorder(16,16,16,16));JPanel filters=new JPanel(new FlowLayout(FlowLayout.LEFT));filters.setOpaque(false);searchInput=field("Search name or enrollment number...");searchInput.setPreferredSize(new Dimension(300,42));yearFilter=new JComboBox<>();courseFilter=new JComboBox<>();JButton clear=button("Clear filters",false);filters.add(searchInput);filters.add(yearFilter);filters.add(courseFilter);filters.add(clear);c.add(filters,BorderLayout.NORTH);studentList=new JPanel();studentList.setBackground(Color.WHITE);studentList.setLayout(new BoxLayout(studentList,BoxLayout.Y_AXIS));c.add(new JScrollPane(studentList),BorderLayout.CENTER);searchInput.getDocument().addDocumentListener(new SimpleDoc(()->renderStudents()));yearFilter.addActionListener(e->renderStudents());courseFilter.addActionListener(e->renderStudents());clear.addActionListener(e->{searchInput.setText("");yearFilter.setSelectedIndex(0);courseFilter.setSelectedIndex(0);renderStudents();});return c;}
    private JPanel settingsPanel(){JPanel p=new JPanel(new GridLayout(1,2,16,0));p.setBackground(Color.WHITE);p.setBorder(new EmptyBorder(16,16,16,16));JPanel a=new JPanel(new BorderLayout(5,8));a.setBackground(Color.WHITE);courseInput=field("Enter course name");JButton addC=button("＋ Add",true);JPanel ca=new JPanel(new BorderLayout(5,5));ca.add(courseInput);ca.add(addC,BorderLayout.EAST);a.add(heading("Manage Courses",18),BorderLayout.NORTH);a.add(ca,BorderLayout.CENTER);courseList=new JPanel();courseList.setLayout(new BoxLayout(courseList,BoxLayout.Y_AXIS));a.add(new JScrollPane(courseList),BorderLayout.SOUTH);JPanel b=new JPanel(new BorderLayout(5,8));b.setBackground(Color.WHITE);yearInput=field("e.g. 2026-2027");JButton addY=button("＋ Add",true);JPanel ya=new JPanel(new BorderLayout(5,5));ya.add(yearInput);ya.add(addY,BorderLayout.EAST);b.add(heading("Manage Academic Years",18),BorderLayout.NORTH);b.add(ya,BorderLayout.CENTER);yearList=new JPanel();yearList.setLayout(new BoxLayout(yearList,BoxLayout.Y_AXIS));b.add(new JScrollPane(yearList),BorderLayout.SOUTH);addC.addActionListener(e->addCourse());addY.addActionListener(e->addYear());return wrapSettings(p,a,b);}
    private JPanel wrapSettings(JPanel p,JPanel a,JPanel b){p.add(a);p.add(b);return p;}
    private JPanel credentialsPanel(){JPanel p=new JPanel();p.setBackground(Color.WHITE);p.setBorder(new EmptyBorder(20,20,20,20));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));p.add(heading("Admin Login Credentials",20));p.add(muted("Change the username and password used to access this dashboard."));currentPass=new JPasswordField();newPass=new JPasswordField();confirmPass=new JPasswordField();JTextField newUser=field("New username");addField(p,"Current Password",currentPass);addField(p,"New Username",newUser);addField(p,"New Password (minimum 8 characters)",newPass);addField(p,"Confirm New Password",confirmPass);credentialMsg=message();p.add(credentialMsg);JButton save=button("Update Login Credentials   →",true);save.addActionListener(e->{String cp=new String(currentPass.getPassword()),np=new String(newPass.getPassword()),cf=new String(confirmPass.getPassword()),nu=newUser.getText().trim();if(!cp.equals(data.password))setMsg(credentialMsg,"Your current password is incorrect.",false);else if(nu.isEmpty())setMsg(credentialMsg,"Please enter a new username.",false);else if(np.length()<8)setMsg(credentialMsg,"Your new password must contain at least 8 characters.",false);else if(!np.equals(cf))setMsg(credentialMsg,"The new passwords do not match.",false);else{data.username=nu;data.password=np;save();setMsg(credentialMsg,"Admin login credentials updated successfully!",true);}});p.add(save);return p;}
    private JPanel studentDetails(){JPanel p=page();p.add(nav("Back to students",()->show("dashboard")));p.add(Box.createVerticalStrut(18));p.add(eyebrow("STUDENT PROFILE"));detailTitle=heading("Student Name",26);p.add(detailTitle);detailEnroll=muted("");p.add(detailEnroll);detailAvatar=heading("S",22);p.add(detailAvatar);JPanel c=card();dName=field("");dEnroll=field("");dPhone=field("");dEmail=field("");dDob=field("YYYY-MM-DD");detailGender=new JComboBox<>(new String[]{"Not specified","Male","Female","Other"});detailCourse=new JComboBox<>();detailYear=new JComboBox<>();dAddress=field("");addField(c,"Full Name",dName);addField(c,"Enrollment Number",dEnroll);addField(c,"Phone Number",dPhone);addField(c,"Email Address",dEmail);addField(c,"Date of Birth",dDob);addField(c,"Gender",detailGender);addField(c,"Course",detailCourse);addField(c,"Academic Year",detailYear);addField(c,"Address",dAddress);editMsg=message();c.add(editMsg);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);editBtn=button("✎ Edit Details",false);deleteBtn=button("Delete Student",false);saveEditBtn=button("Save Changes",true);cancelEditBtn=button("Cancel",false);actions.add(editBtn);actions.add(deleteBtn);editActions=new JPanel(new FlowLayout(FlowLayout.LEFT));editActions.setOpaque(false);editActions.add(cancelEditBtn);editActions.add(saveEditBtn);c.add(actions);c.add(editActions);editActions.setVisible(false);editBtn.addActionListener(e->editMode(true));cancelEditBtn.addActionListener(e->openDetails(selected));saveEditBtn.addActionListener(e->saveEdit());deleteBtn.addActionListener(e->deleteSelected());p.add(c);return p;}
    private void show(String name){cards.show(root,name);}
    private void registerStudent(){String n=regName.getText().trim(),em=regEmail.getText().trim().toLowerCase(),ph=regPhone.getText().trim(),co=(String)regCourse.getSelectedItem(),yr=(String)regYear.getSelectedItem();if(n.isEmpty()||em.isEmpty()||ph.isEmpty()||co==null||yr==null){setMsg(regMsg,"Please complete all the required fields.",false);return;}String digits=normalize(ph);if(digits.length()<10||digits.length()>15){setMsg(regMsg,"Please enter a valid phone number.",false);return;}if(data.students.stream().anyMatch(s->s.email.equalsIgnoreCase(em))){setMsg(regMsg,"A student record with this email already exists.",false);return;}if(data.students.stream().anyMatch(s->normalize(s.phone).equals(digits))){setMsg(regMsg,"A student record with this phone number already exists.",false);return;}String enrollment="25016"+String.format("%07d",++data.counter);Student s=new Student(UUID.randomUUID().toString(),n,em,ph,co,yr,enrollment);data.students.add(s);currentEnrollment=enrollment;save();successNumber.setText(enrollment);copyMsg.setText(" ");show("success");}
    private void findEnrollment(){String ph=normalize(findPhone.getText()),em=findEmail.getText().trim().toLowerCase();if(ph.length()<10||ph.length()>15||em.isEmpty()){setMsg(findMsg,"Please enter a valid phone number and email address.",false);return;}Student s=data.students.stream().filter(x->normalize(x.phone).equals(ph)&&x.email.equalsIgnoreCase(em)).findFirst().orElse(null);if(s==null){setMsg(findMsg,"No matching student record found. Please check your details.",false);findResult.setText("");}else{setMsg(findMsg,"Matching student record found:",true);findResult.setText("Name: "+s.name+"    |    Course: "+s.course+"    |    Enrollment: "+s.enrollment);}}
    private String normalize(String s){return s==null?"":s.replaceAll("\\D","");}
    private void renderDashboard(){totalLabel.setText("TOTAL STUDENTS: "+data.students.size());refreshFilters();renderStudents();renderSettings();}
    private void refreshFilters(){yearFilter.setModel(new DefaultComboBoxModel<>(withAll(data.years).toArray(new String[0])));courseFilter.setModel(new DefaultComboBoxModel<>(withAll(data.courses).toArray(new String[0])));}
    private List<String> withAll(List<String> values){List<String> r=new ArrayList<>();r.add("All");r.addAll(values);return r;}
    private void renderSettings(){courseList.removeAll();for(String s:new ArrayList<>(data.courses)){courseList.add(manageRow(s,true));}yearList.removeAll();for(String s:new ArrayList<>(data.years)){yearList.add(manageRow(s,false));}courseList.revalidate();courseList.repaint();yearList.revalidate();yearList.repaint();}
    private JPanel manageRow(String value,boolean course){JPanel row=new JPanel(new BorderLayout());row.setBackground(Color.WHITE);row.setBorder(new EmptyBorder(5,3,5,3));row.add(new JLabel(value),BorderLayout.CENTER);JButton remove=button("Remove",false);remove.addActionListener(e->{boolean used=data.students.stream().anyMatch(s->course?s.course.equals(value):s.year.equals(value));if(used){msg("Cannot remove",course?"This course is assigned to existing students and cannot be removed.":"This academic year is assigned to existing students and cannot be removed.");return;}if(JOptionPane.showConfirmDialog(this,"Remove this "+(course?"course":"academic year")+"?","Confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){(course?data.courses:data.years).remove(value);save();renderSettings();refreshFilters();}});row.add(remove,BorderLayout.EAST);return row;}
    private void addCourse(){String s=courseInput.getText().trim();if(s.isEmpty())return;if(data.courses.stream().anyMatch(x->x.equalsIgnoreCase(s))){msg("Duplicate","This course already exists.");return;}data.courses.add(s);courseInput.setText("");save();renderSettings();refreshFilters();}
    private void addYear(){String s=yearInput.getText().trim();if(s.isEmpty())return;if(data.years.contains(s)){msg("Duplicate","This academic year already exists.");return;}data.years.add(s);yearInput.setText("");save();renderSettings();refreshFilters();}
    private void renderStudents(){if(studentList==null)return;studentList.removeAll();String q=searchInput.getText().trim().toLowerCase(),y=(String)yearFilter.getSelectedItem(),c=(String)courseFilter.getSelectedItem();List<Student> filtered=data.students.stream().filter(s->(s.name.toLowerCase().contains(q)||s.enrollment.toLowerCase().contains(q))&&(y==null||y.equals("All")||s.year.equals(y))&&(c==null||c.equals("All")||s.course.equals(c))).collect(Collectors.toList());if(filtered.isEmpty())studentList.add(muted("No students found. There are no matching student records."));for(Student s:filtered){JButton b=button("●  "+s.name+"     |     "+s.enrollment+"     →",false);b.setHorizontalAlignment(SwingConstants.LEFT);b.setAlignmentX(LEFT_ALIGNMENT);b.addActionListener(e->openDetails(s));studentList.add(b);studentList.add(Box.createVerticalStrut(7));}studentList.revalidate();studentList.repaint();if(totalLabel!=null)totalLabel.setText("TOTAL STUDENTS: "+data.students.size());}
    private void openDetails(Student s){selected=s;if(s==null)return;detailTitle.setText(s.name);detailEnroll.setText(s.enrollment);detailAvatar.setText(s.name.substring(0,1).toUpperCase());dName.setText(s.name);dEnroll.setText(s.enrollment);dPhone.setText(s.phone);dEmail.setText(s.email);dDob.setText(s.dob);dAddress.setText(s.address);detailGender.setSelectedItem(s.gender.isEmpty()?"Not specified":s.gender);detailCourse.setModel(new DefaultComboBoxModel<>(withCurrent(data.courses,s.course).toArray(new String[0])));detailYear.setModel(new DefaultComboBoxModel<>(withCurrent(data.years,s.year).toArray(new String[0])));detailCourse.setSelectedItem(s.course);detailYear.setSelectedItem(s.year);editMode(false);setMsg(editMsg," ",false);show("details");}
    private List<String> withCurrent(List<String> values,String current){List<String> a=new ArrayList<>(values);if(current!=null&&!current.isEmpty()&&!a.contains(current))a.add(current);return a;}
    private void editMode(boolean enabled){for(JComponent c:Arrays.asList(dName,dEnroll,dPhone,dEmail,dDob,dAddress,detailGender,detailCourse,detailYear))c.setEnabled(enabled);editBtn.setVisible(!enabled);deleteBtn.setVisible(!enabled);editActions.setVisible(enabled);}
    private void saveEdit(){String n=dName.getText().trim(),en=dEnroll.getText().trim(),ph=dPhone.getText().trim(),em=dEmail.getText().trim().toLowerCase(),co=(String)detailCourse.getSelectedItem(),yr=(String)detailYear.getSelectedItem();if(n.isEmpty()||en.isEmpty()||ph.isEmpty()||em.isEmpty()||co==null||yr==null){setMsg(editMsg,"Please complete all required fields.",false);return;}String digits=normalize(ph);if(digits.length()<10||digits.length()>15){setMsg(editMsg,"Please enter a valid phone number.",false);return;}for(Student s:data.students)if(!s.id.equals(selected.id)){if(s.enrollment.equals(en)){setMsg(editMsg,"This enrollment number is already assigned to another student.",false);return;}if(s.email.equalsIgnoreCase(em)){setMsg(editMsg,"This email is already assigned to another student.",false);return;}if(normalize(s.phone).equals(digits)){setMsg(editMsg,"This phone number is already assigned to another student.",false);return;}}selected.name=n;selected.enrollment=en;selected.phone=ph;selected.email=em;selected.course=co;selected.year=yr;selected.dob=dDob.getText().trim();selected.gender=Objects.toString(detailGender.getSelectedItem(),"");if(selected.gender.equals("Not specified"))selected.gender="";selected.address=dAddress.getText().trim();save();detailTitle.setText(n);detailEnroll.setText(en);editMode(false);setMsg(editMsg,"Student details updated successfully.",true);renderStudents();}
    private void deleteSelected(){if(selected==null)return;if(JOptionPane.showConfirmDialog(this,"Permanently delete "+selected.name+"?\nEnrollment Number: "+selected.enrollment+"\n\nThis action cannot be undone.","Delete Student",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;data.students.removeIf(s->s.id.equals(selected.id));selected=null;save();renderStudents();show("dashboard");}
    private void msg(String title,String body){JOptionPane.showMessageDialog(this,body,title,JOptionPane.INFORMATION_MESSAGE);}
    private static class SimpleDoc implements javax.swing.event.DocumentListener{Runnable r;SimpleDoc(Runnable r){this.r=r;}public void insertUpdate(javax.swing.event.DocumentEvent e){r.run();}public void removeUpdate(javax.swing.event.DocumentEvent e){r.run();}public void changedUpdate(javax.swing.event.DocumentEvent e){r.run();}}
    public static void main(String[] args){SwingUtilities.invokeLater(()->{try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());}catch(Exception ignored){}new EnrollmentPortal().setVisible(true);});}
}
